-- Master products (Radient Pharma price list) import SQL
-- Source file: external_files/master_data/products_Radient_Pharma_Price_List.xlxs
-- Note: file is tab-separated UTF-8 text.

CREATE TABLE `master_products_radient_pharma` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `medicine_text_id` bigint(20) unsigned DEFAULT NULL,
  `product_name` varchar(255) NOT NULL,
  `net_weight_or_size` varchar(100) DEFAULT NULL,
  `mrp_rate` decimal(10,2) DEFAULT NULL,
  `shipper_size_pcs` int(11) DEFAULT NULL,
  `category` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `formula_composition` text DEFAULT NULL,
  `normalized_product_name` varchar(255) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_master_products_radient_name_size_category` (`normalized_product_name`,`net_weight_or_size`,`category`),
  KEY `fk_mpr_medicine_text` (`medicine_text_id`),
  CONSTRAINT `fk_mpr_medicine_text` FOREIGN KEY (`medicine_text_id`) REFERENCES `master_text_medicines` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=161 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


